// src/Component/Login.js
import React, { useState, useEffect, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import "./login.css";

function Login() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [errors, setErrors] = useState({});
  const navigate = useNavigate();

  // -------------------
  // Cleanup old tokens on mount
  // -------------------
  useEffect(() => {
    localStorage.removeItem("access_token");
    localStorage.removeItem("refresh_token");
  }, []);

  // -------------------
  // Refresh access token
  // -------------------
  const refreshAccessToken = useCallback(async () => {
    const refreshToken = localStorage.getItem("refresh_token");
    if (!refreshToken) return;

    try {
      const response = await fetch(
        "http://127.0.0.1:8000/api/auth/token/refresh/",
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ refresh: refreshToken }),
        }
      );

      const data = await response.json();

      if (response.ok) {
        localStorage.setItem("access_token", data.access);
        console.log("Access token refreshed");
      } else {
        console.error("Refresh token failed:", data);
        localStorage.removeItem("access_token");
        localStorage.removeItem("refresh_token");
        navigate("/login");
      }
    } catch (err) {
      console.error("Network error while refreshing token:", err);
      navigate("/login");
    }
  }, [navigate]);

  // -------------------
  // Auto-refresh token every 10 seconds (for testing)
  // -------------------
  useEffect(() => {
    refreshAccessToken(); // immediate refresh on mount
    const interval = setInterval(refreshAccessToken, 10 * 1000); // 10s
    return () => clearInterval(interval);
  }, [refreshAccessToken]);

  // -------------------
  // Helper for authenticated API calls
  // -------------------
  const authFetch = async (url, options = {}) => {
    const token = localStorage.getItem("access_token");
    const headers = {
      "Content-Type": "application/json",
      Authorization: token ? `Bearer ${token}` : "",
      ...options.headers,
    };
    const response = await fetch(url, { ...options, headers });

    if (response.status === 401) {
      // Token expired → refresh
      await refreshAccessToken();
      const newToken = localStorage.getItem("access_token");
      headers.Authorization = `Bearer ${newToken}`;
      return fetch(url, { ...options, headers });
    }

    return response;
  };

  // -------------------
  // Login submit
  // -------------------
  const handleSubmit = async (e) => {
    e.preventDefault();
    setErrors({});

    if (!email || !password) {
      setErrors({ form: "Email and password are required" });
      return;
    }

    try {
      // Using authFetch even for login
      const response = await authFetch("http://127.0.0.1:8000/api/auth/token/", {
        method: "POST",
        body: JSON.stringify({ username: email, password }),
      });

      const data = await response.json();

      if (response.ok) {
        localStorage.setItem("access_token", data.access);
        localStorage.setItem("refresh_token", data.refresh);

        toast.success("🎉 Login successful!", {
          position: "top-right",
          autoClose: 3000,
        });

        setTimeout(() => navigate("/dashboard"), 1000);
      } else {
        setErrors({ form: data.detail || "Invalid credentials" });
      }
    } catch (err) {
      console.error("Network error:", err);
      setErrors({ form: "Network error, try again later" });
    }
  };

  return (
    <div className="main">
      <ToastContainer />
      <div className="login-container">
        <div className="login-header">
          <h2>Login</h2>
        </div>
        <form onSubmit={handleSubmit} className="login-form" noValidate>
          {errors.form && <p className="error-text">{errors.form}</p>}

          <div className="input-group">
            <label>Username</label>
            <input
              type="text"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>

          <div className="input-group">
            <label>Password</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>

          <button type="submit" className="login-button">
            Login
          </button>
        </form>
      </div>
    </div>
  );
}

export default Login;
